#include "final04.hpp"
#include <filesystem>
#include <fstream>
#include <sstream>
#include <iostream>
#include <iomanip>
#include <map>
#include <set>
#include <cmath>
namespace fs=std::filesystem;
namespace {
std::vector<std::string> split(std::string s,char delim='\t'){if(!s.empty()&&s.back()=='\r')s.pop_back();std::stringstream in(s);std::string t;std::vector<std::string>v;while(std::getline(in,t,delim))v.push_back(t);return v;}
struct Data{cv::Mat x,y;std::vector<std::string>hash;};
Data read(const fs::path& path){std::ifstream in(path);if(!in)throw std::runtime_error("Missing feature table");Data d;std::string line;std::getline(in,line);std::set<std::string>hashes;while(std::getline(in,line)){auto v=split(line);if(v.size()!=8||std::stoi(v[0])!=d.x.rows||!hashes.insert(v[3]).second)throw std::runtime_error("Invalid/duplicate feature row");auto numbers=split(v[7],';');if(numbers.size()!=66)throw std::runtime_error("Expected66 features");cv::Mat x(1,66,CV_64F);for(int j=0;j<66;j++)x.at<double>(j)=std::stod(numbers[j]);cv::Mat y=(cv::Mat_<double>(1,2)<<std::stod(v[5]),std::stod(v[6]));if(!cv::checkRange(x)||!cv::checkRange(y))throw std::runtime_error("Nonfinite row");d.x.push_back(x);d.y.push_back(y);d.hash.push_back(v[3]);}if(d.x.rows!=715)throw std::runtime_error("Expected715 rows");return d;}
void fresh(const fs::path&p){if(fs::exists(p))throw std::runtime_error("Output exists; choose new path");}
int run(const std::vector<std::string>&a){cv::setNumThreads(1);if(a.size()<1)throw std::runtime_error("train FEATURES MODEL META | verify FEATURES EXPECTED_OOF OUTPUT | audit ASSETS FEATURES IMAGE_MANIFEST OUTPUT");
 if(a[0]=="train"&&a.size()==4){fresh(fs::u8path(a[2]));fresh(fs::u8path(a[3]));auto d=read(fs::u8path(a[1]));final04::LinearModel m;m.fit(d.x,d.y);m.save(a[2]);final04::LinearModel loaded;loaded.load(a[2]);if(cv::norm(m.predict(d.x),loaded.predict(d.x),cv::NORM_INF)>1e-12)throw std::runtime_error("Serialization parity failure");cv::FileStorage meta(a[3],cv::FileStorage::WRITE|cv::FileStorage::FORMAT_JSON);meta<<"training_images"<<d.x.rows<<"training_min"<<"[";for(int k=0;k<2;k++){double mn;cv::minMaxLoc(d.y.col(k),&mn);meta<<mn;}meta<<"]"<<"training_max"<<"[";for(int k=0;k<2;k++){double mx;cv::minMaxLoc(d.y.col(k),nullptr,&mx);meta<<mx;}meta<<"]"<<"scope"<<"All715 development photos fitted for deployment. Cross-validation evidence is separate.";std::cout<<"TRAIN715 serialization parity PASS\n";return 0;}
 if(a[0]=="verify"&&a.size()==4){fresh(fs::u8path(a[3]));auto d=read(fs::u8path(a[1]));std::ifstream in(fs::u8path(a[2]));if(!in)throw std::runtime_error("Missing expected OOF");std::map<int,int>fold;std::map<int,cv::Vec2d>expected;std::string l;std::getline(in,l);while(std::getline(in,l)){auto v=split(l);if(v.size()!=12)throw std::runtime_error("OOF schema");int id=std::stoi(v[4]),f=std::stoi(v[1]);if(f<0||f>4||id<0||id>=715||fold.count(id))throw std::runtime_error("Bad OOF membership");fold[id]=f;expected[id]={std::stod(v[7]),std::stod(v[8])};if(std::abs(std::stod(v[5])-d.y.at<double>(id,0))>1e-12||std::abs(std::stod(v[6])-d.y.at<double>(id,1))>1e-12)throw std::runtime_error("Target identity mismatch");}if(fold.size()!=715)throw std::runtime_error("Incomplete OOF");std::ofstream out(fs::u8path(a[3]));out<<"id\tfold\tpred_Y\tpred_T\texpected_Y\texpected_T\tpass\n"<<std::setprecision(17);double delta=0,maxY=0,maxT=0;int pass=0;for(int f=0;f<5;f++){cv::Mat x,y;for(int i=0;i<715;i++)if(fold.at(i)!=f){x.push_back(d.x.row(i));y.push_back(d.y.row(i));}final04::LinearModel m;m.fit(x,y);for(int i=0;i<715;i++)if(fold.at(i)==f){auto p=m.predict(d.x.row(i));double py=p.at<double>(0),pt=p.at<double>(1),ey=std::abs(py-d.y.at<double>(i,0)),et=std::abs(pt-d.y.at<double>(i,1));delta=std::max(delta,std::max(std::abs(py-expected[i][0]),std::abs(pt-expected[i][1])));maxY=std::max(maxY,ey);maxT=std::max(maxT,et);bool ok=ey<=.045&&et<=.01;pass+=ok;out<<i<<'\t'<<f<<'\t'<<py<<'\t'<<pt<<'\t'<<expected[i][0]<<'\t'<<expected[i][1]<<'\t'<<ok<<'\n';}}std::cout<<std::setprecision(17)<<"CV n=715 pass="<<pass<<" max_Y="<<maxY<<" max_T="<<maxT<<" parity_max="<<delta<<'\n';return delta>1e-7?1:0;}
 if(a[0]=="audit"&&a.size()==5){fresh(fs::u8path(a[4]));auto d=read(fs::u8path(a[2]));final04::Estimator observer(a[1]);final04::LinearModel model;model.load((fs::u8path(a[1])/"huber_linear66.yml").u8string());alignment_detail::Observer geometry(fs::u8path(a[1]));std::ifstream list(fs::u8path(a[3]));if(!list)throw std::runtime_error("Missing image manifest");std::ofstream out(fs::u8path(a[4]));out<<"id\tfeature_max_delta\tpred_max_delta\tpass\n"<<std::setprecision(17);std::string line;std::getline(list,line);int n=0,fail=0;while(std::getline(list,line)){auto v=split(line);if(v.size()!=2)throw std::runtime_error("Expected id,path");int i=std::stoi(v[0]);auto path=fs::u8path(v[1]);if(alignment_detail::sha256(path)!=d.hash.at(i))throw std::runtime_error("Original image hash mismatch");auto image=alignment_detail::read_gray(path);auto r=observer.predict(image);auto x=final04::features(r.raw110.colRange(0,102),r.raw110.colRange(102,110),geometry.block_centers());auto p=model.predict(d.x.row(i));double dx=cv::norm(x,d.x.row(i),cv::NORM_INF),dp=std::max(std::abs(r.pose.y-p.at<double>(0)),std::abs(r.pose.t-p.at<double>(1)));bool ok=dx<=1e-6&&dp<=1e-7;out<<i<<'\t'<<dx<<'\t'<<dp<<'\t'<<ok<<'\n';out.flush();n++;fail+=!ok;}if(n==0)throw std::runtime_error("No audit images");std::cout<<"IMAGE_AUDIT n="<<n<<" failures="<<fail<<'\n';return fail?1:0;}
 throw std::runtime_error("Invalid command");}
}
